  "trailers": [
    {
      "title": "Betrayed at the Altar",
      "moment_ids": ["M001", "M002", "M007", "M008"],
      "hook": "The Matriarch coldly tells Juliana that Gerald is not waiting for her.",
      "cliffhanger": "The Bearded Stranger drops to one knee offering a silver ring, leaving Juliana's fate with him unresolved.",
      "why": "Opens on the wedding betrayal, then pivots to a mysterious rescuer proposing marriage, selling the core twist."
    },
    {
      "title": "The Scarred Soldier's Secret",
      "moment_ids": ["M033", "M034", "M070", "M071"],
      "hook": "Alexander appears bloodied in the doorway, dismissing his wounds as nothing.",
      "cliffhanger": "Alexander learns his mother is a prisoner and decides to let his enemies believe he is dead a little longer.",
      "why": "Starts with visceral danger, reveals his battle scars, then drops the ducal identity secret and a cold revenge vow."
    },
    {
      "title": "Poison in Ashbury Manor",
      "moment_ids": ["M077", "M085", "M086", "M088"],
      "hook": "Prudence drops to her knees begging Juliana to save her seven-year-old brother.",
      "cliffhanger": "Juliana is trapped with an unfinished cure as the door latch turns and the door cracks open.",
      "why": "Establishes Juliana as a healer, reveals the Duchess is being poisoned with arsenic, and cuts on a life-or-death intrusion."
    },
    {
      "title": "The Witch Trial",
      "moment_ids": ["M117", "M120", "M124", "M160"],
      "hook": "Catherine enters the dungeon in an ornate gown and taunts a chained Juliana.",
      "cliffhanger": "The cathedral doors explode in a fireball and armed silhouettes emerge through the smoke as Juliana turns in awe.",
      "why": "Builds from cruel taunting to a branding iron threat, then cuts to the explosive rescue before the outcome is shown."
    }
  ]
}
